token. If enabled, `site_key` must reference an Express site key.

=item * C<< $msg->requested_uri() >> / C<< $msg->requested_uri($value) >>

Type: C<String>

Optional. The URI resource the user requested that triggered an assessment.

=item * C<< $msg->waf_token_assessment() >> / C<< $msg->waf_token_assessment($value) >>

Type: C<Bool>

Optional. Flag for running Web Application Firewall (WAF) token assessment.
If enabled, the token must be specified, and have been created by a
WAF-enabled key.

=item * C<< $msg->ja3() >> / C<< $msg->ja3($value) >>

Type: C<String>

Optional. JA3 fingerprint for SSL clients. To learn how to compute this
fingerprint, please refer to https://github.com/salesforce/ja3.

=item * C<< $msg->ja4() >> / C<< $msg->ja4($value) >>

Type: C<String>

Optional. JA4 fingerprint for SSL clients. To learn how to compute this
fingerprint, please refer to https://github.com/FoxIO-LLC/ja4.

=item * C<< $msg->headers() >> / C<< $msg->headers($value) >>

Type: C<String>

Optional. HTTP header information about the request.

=item * C<< $msg->firewall_policy_evaluation() >> / C<< $msg->firewall_policy_evaluation($value) >>

Type: C<Bool>

Optional. Flag for enabling firewall policy config assessment.
If this flag is enabled, the firewall policy is evaluated and a
suggested firewall action is returned in the response.

=item * C<< $msg->transaction_data() >> / C<< $msg->transaction_data($value) >>

Type: C<Message> (L<Google::Cloud::Recaptchaenterprise::V1::Recaptchaenterprise::TransactionData>)

Optional. Data describing a payment transaction to be assessed. Sending
this data enables reCAPTCHA Enterprise Fraud Prevention and the
FraudPreventionAssessment component in the response.

=item * C<< $msg->user_info() >> / C<< $msg->user_info($value) >>

Type: C<Message> (L<Google::Cloud::Recaptchaenterprise::V1::Recaptchaenterprise::UserInfo>)

Optional. Information about the user that generates this event, when they
can be identified. They are often identified through the use of an account
for logged-in requests or login/registration requests, or by providing user
identifiers for guest actions like checkout.

=item * C<< $msg->fraud_prevention() >> / C<< $msg->fraud_prevention($value) >>

Type: C<Enum> (L<Google::Cloud::Recaptchaenterprise::V1::Event::FraudPrevention>)

Optional. The Fraud Prevention setting for this assessment.

=back

=head3 Enum: Event::FraudPrevention

=over 4

=item * C<FRAUD_PREVENTION_UNSPECIFIED> => C<0>

=item * C<ENABLED> => C<1>

=item * C<DISABLED> => C<2>

=back

=head2 Google::Cloud::Recaptchaenterprise::V1::Recaptchaenterprise::TransactionData

Transaction data associated with a payment protected by reCAPTCHA Enterprise.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->transaction_id() >> / C<< $msg->transaction_id($value) >>

Type: C<String>

Unique identifier for the transaction. This custom identifier can be used
to reference this transaction in the future, for example, labeling a refund
or chargeback event. Two attempts at the same transaction should use the
same transaction id.

=item * C<< $msg->payment_method() >> / C<< $msg->payment_method($value) >>

Type: C<String>

Optional. The payment method for the transaction. The allowed values are:

* credit-card
* debit-card
* gift-card
* processor-{name} (If a third-party is used, for example,
processor-paypal)
* custom-{name} (If an alternative method is used, for example,
custom-crypto)

=item * C<< $msg->card_bin() >> / C<< $msg->card_bin($value) >>

Type: C<String>

Optional. The Bank Identification Number - generally the first 6 or 8
digits of the card.

=item * C<< $msg->card_last_four() >> / C<< $msg->card_last_four($value) >>

Type: C<String>

Optional. The last four digits of the card.

=item * C<< $msg->currency_code() >> / C<< $msg->currency_code($value) >>

Type: C<String>

Optional. The currency code in ISO-4217 format.

=item * C<< $msg->value() >> / C<< $msg->value($value) >>

Type: C<Double>

Optional. The decimal value of the transaction in the specified currency.

=item * C<< $msg->shipping_value() >> / C<< $msg->shipping_value($value) >>

Type: C<Double>

Optional. The value of shipping in the specified currency. 0 for free or no
shipping.

=item * C<< $msg->shipping_address() >> / C<< $msg->shipping_address($value) >>

Type: C<Message> (L<Google::Cloud::Recaptchaenterprise::V1::Recaptchaenterprise::TransactionData::Address>)

Optional. Destination address if this transaction involves shipping a
physical item.

=item * C<< $msg->billing_address() >> / C<< $msg->billing_address($value) >>

Type: C<Message> (L<Google::Cloud::Recaptchaenterprise::V1::Recaptchaenterprise::TransactionData::Address>)

Optional. Address associated with the payment method when applicable.

=item * C<< $msg->user() >> / C<< $msg->user($value) >>

Type: C<Message> (L<Google::Cloud::Recaptchaenterprise::V1::Recaptchaenterprise::TransactionData::User>)

Optional. Information about the user paying/initiating the transaction.

=item * C<< $msg->merchants() >> / C<< $msg->merchants($value) >>

Type: C<Message> (L<Google::Cloud::Recaptchaenterprise::V1::Recaptchaenterprise::TransactionData::User>)

Optional. Information about the user or users fulfilling the transaction.

=item * C<< $msg->items() >> / C<< $msg->items($value) >>

Type: C<Message> (L<Google::Cloud::Recaptchaenterprise::V1::Recaptchaenterprise::TransactionData::Item>)

Optional. Items purchased in this transaction.

=item * C<< $msg->gateway_info() >> / C<< $msg->gateway_info($value) >>

Type: C<Message> (L<Google::Cloud::Recaptchaenterprise::V1::Recaptchaenterprise::TransactionData::GatewayInfo>)

Optional. Information about the payment gateway's response to the
transaction.

=back

=head2 Google::Cloud::Recaptchaenterprise::V1::Recaptchaenterprise::UserInfo

User information associated with a request protected by reCAPTCHA Enterprise.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->create_account_time() >> / C<< $msg->create_account_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Optional. Creation time for this account associated with this user. Leave
blank for non logged-in actions, guest checkout, or when there is no
account associated with the current user.

=item * C<< $msg->account_id() >> / C<< $msg->account_id($value) >>

Type: C<String>

Optional. For logged-in requests or login/registration requests, the unique
account identifier associated with this user. You can use the username if
it is stable (meaning it is the same for every request associated with the
same user), or any stable user ID of your choice. Leave blank for non
logged-in actions or guest checkout.

=item * C<< $msg->user_ids() >> / C<< $msg->user_ids($value) >>

Type: C<Message> (L<Google::Cloud::Recaptchaenterprise::V1::Recaptchaenterprise::UserId>)

Optional. Identifiers associated with this user or request.

=back

=head2 Google::Cloud::Recaptchaenterprise::V1::Recaptchaenterprise::UserId

An identifier associated with a user.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->email() >> / C<< $msg->email($value) >>

Type: C<String>

Optional. An email address.

=item * C<< $msg->phone_number() >> / C<< $msg->phone_number($value) >>

Type: C<String>

Optional. A phone number. Should use the E.164 format.

=item * C<< $msg->username() >> / C<< $msg->username($value) >>

Type: C<String>

Optional. A unique username, if different from all the other identifiers
and `account_id` that are provided. Can be a unique login handle or
display name for a user.

=back

=head2 Google::Cloud::Recaptchaenterprise::V1::Recaptchaenterprise::RiskAnalysis

Risk analysis result for an event.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->score() >> / C<< $msg->score($value) >>

Type: C<Float>

Output only. Legitimate event score from 0.0 to 1.0.
(1.0 means very likely legitimate traffic while 0.0 means very likely
non-legitimate traffic).

=item * C<< $msg->reasons() >> / C<< $msg->reasons($value) >>

Type: C<Enum> (L<Google::Cloud::Recaptchaenterprise::V1::RiskAnalysis::ClassificationReason>)

Output only. Reasons contributing to the risk analysis verdict.

=item * C<< $msg->extended_verdict_reasons() >> / C<< $msg->extended_verdict_reasons($value) >>

Type: C<String>

Output only. Additional reasons contributing to the risk analysis verdict.
These reasons are available to Enterprise tier projects only. Contact sales
for more information.
The set of reasons is subject to change.

=item * C<< $msg->last_challenge_type() >> / C<< $msg->last_challenge_type($value) >>

Type: C<Enum> (L<Google::Cloud::Recaptchaenterprise::V1::ChallengeType>)

Output only. Type of the last challenge presented to the user for
Universal, `POLICY_BASED_CHALLENGE` and `INVISIBLE` keys. The field is only
set when a challenge was presented to the user.

=item * C<< $msg->challenge() >> / C<< $msg->challenge($value) >>

Type: C<Enum> (L<Google::Cloud::Recaptchaenterprise::V1::RiskAnalysis::Challenge>)

Output only. Challenge information for Universal, `POLICY_BASED_CHALLENGE`
and `INVISIBLE` keys.

=item * C<< $msg->verified_bots() >> / C<< $msg->verified_bots($value) >>

Type: C<Message> (L<Google::Cloud::Recaptchaenterprise::V1::Recaptchaenterprise::Bot>)

Output only. Bots with identities that have been verified by reCAPTCHA and
detected in the event.

=back

=head3 Enum: RiskAnalysis::ClassificationReason

=over 4

=item * C<CLASSIFICATION_REASON_UNSPECIFIED> => C<0>

=item * C<AUTOMATION> => C<1>

=item * C<UNEXPECTED_ENVIRONMENT> => C<2>

=item * C<TOO_MUCH_TRAFFIC> => C<3>

=item * C<UNEXPECTED_USAGE_PATTERNS> => C<4>

=item * C<LOW_CONFIDENCE_SCORE> => C<5>

=item * C<SUSPECTED_CARDING> => C<6>

=item * C<SUSPECTED_CHARGEBACK> => C<7>

=back

=head3 Enum: RiskAnalysis::Challenge

=over 4

=item * C<CHALLENGE_UNSPECIFIED> => C<0>

=item * C<NOCAPTCHA> => C<1>

=item * C<PASSED> => C<2>

=item * C<FAILED> => C<3>

=back

=head2 Google::Cloud::Recaptchaenterprise::V1::Recaptchaenterprise::Bot

Bot information and metadata.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Optional. Enumerated string value that indicates the identity of the bot,
formatted in kebab-case. Current example values include the following:

* google-agent - AI_AGENT
* browser-base - AI_AGENT
* chat-gpt - AI_AGENT
* aws-bedrock - AI_AGENT
* cybaa-bot - AI_AGENT
* cloudflare - AI_AGENT
* payhawk - AI_AGENT
* duck-duck-go - SEARCH_INDEXER
* mediaboard - CONTENT_SCRAPER
* marker-io - AI_AGENT
* broadcom - AI_AGENT
* anchor-browser - AI_AGENT
* shopify - AI_AGENT
* stackscope - CONTENT_SCRAPER
* manus - AI_AGENT
* kernel-sh - AI_AGENT
* zvelo - SEARCH_INDEXER

Ensure that your applications can handle identifier values not explicitly
listed here. Deprecated values might take some time to stop showing
up in responses. New values can be pushed so this list should be taken
as non exhaustive.

=item * C<< $msg->bot_type() >> / C<< $msg->bot_type($value) >>

Type: C<Enum> (L<Google::Cloud::Recaptchaenterprise::V1::Bot::BotType>)

Optional. Enumerated field representing the type of bot.

=back

=head3 Enum: Bot::BotType

=over 4

=item * C<BOT_TYPE_UNSPECIFIED> => C<0>

=item * C<AI_AGENT> => C<1>

=item * C<CONTENT_SCRAPER> => C<2>

=item * C<SEARCH_INDEXER> => C<3>

=back

=head2 Google::Cloud::Recaptchaenterprise::V1::Recaptchaenterprise::TokenProperties

Properties of the provided event token.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->valid() >> / C<< $msg->valid($value) >>

Type: C<Bool>

Output only. Indicates whether the provided user response token is valid.
If `false`, the token is invalid, either because the user failed the
challenge or for a reason provided in the `invalid_reason` field.

=item * C<< $msg->invalid_reason() >> / C<< $msg->invalid_reason($value) >>

Type: C<Enum> (L<Google::Cloud::Recaptchaenterprise::V1::TokenProperties::InvalidReason>)

Output only. Reason associated with the response when valid = false.

=item * C<< $msg->create_time() >> / C<< $msg->create_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The timestamp corresponding to the generation of the token.

=item * C<< $msg->hostname() >> / C<< $msg->hostname($value) >>

Type: C<String>

Output only. The hostname of the page on which the token was generated (Web
keys only).

=item * C<< $msg->android_package_name() >> / C<< $msg->android_package_name($value) >>

Type: C<String>

Output only. The name of the Android package with which the token was
generated (Android keys only).

=item * C<< $msg->ios_bundle_id() >> / C<< $msg->ios_bundle_id($value) >>

Type: C<String>

Output only. The ID of the iOS bundle with which the token was generated
(iOS keys only).

=item * C<< $msg->action() >> / C<< $msg->action($value) >>

Type: C<String>

Output only. Action name provided at token generation.

=back

