Type: C<Enum> (L<Google::Cloud::Recaptchaenterprise::V1::WebKeySettings::ChallengeSecurityPreference>)

Optional. Settings for the frequency and difficulty at which this key
triggers captcha challenges. This should only be specified for
`IntegrationType` CHECKBOX, INVISIBLE or POLICY_BASED_CHALLENGE.

=item * C<< $msg->challenge_settings() >> / C<< $msg->challenge_settings($value) >>

Type: C<Message> (L<Google::Cloud::Recaptchaenterprise::V1::Recaptchaenterprise::WebKeySettings::ChallengeSettings>)

