=head2 Google::Cloud::Recaptchaenterprise::V1::Recaptchaenterprise::SearchRelatedAccountGroupMembershipsRequest

The request message to search related account group memberships.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->project() >> / C<< $msg->project($value) >>

Type: C<String>

Required. The name of the project to search related account group
memberships from. Specify the project name in the following format:
`projects/{project}`.

=item * C<< $msg->account_id() >> / C<< $msg->account_id($value) >>

Type: C<String>

Optional. The unique stable account identifier used to search connections.
The identifier should correspond to an `account_id` provided in a previous
`CreateAssessment` or `AnnotateAssessment` call. Either hashed_account_id
or account_id must be set, but not both.

=item * C<< $msg->hashed_account_id() >> / C<< $msg->hashed_account_id($value) >>

Type: C<Bytes>

Optional. Deprecated: use `account_id` instead.
The unique stable hashed account identifier used to search connections. The
identifier should correspond to a `hashed_account_id` provided in a
previous `CreateAssessment` or `AnnotateAssessment` call. Either
hashed_account_id or account_id must be set, but not both.

=item * C<< $msg->page_size() >> / C<< $msg->page_size($value) >>

Type: C<Int32>

Optional. The maximum number of groups to return. The service might return
fewer than this value. If unspecified, at most 50 groups are returned. The
maximum value is 1000; values above 1000 are coerced to 1000.

=item * C<< $msg->page_token() >> / C<< $msg->page_token($value) >>

Type: C<String>

Optional. A page token, received from a previous
`SearchRelatedAccountGroupMemberships` call. Provide this to retrieve the
subsequent page.

When paginating, all other parameters provided to
`SearchRelatedAccountGroupMemberships` must match the call that provided
the page token.

=back

